      // Subtitle actions - subtitles are now created as text clips on a "Captions" track
      /**
       * Add a subtitle as a text clip on a Captions track
       */
      addSubtitle: async (subtitle) => {
        const { project, addTrack, createTextClip } = get();
        let captionsTrack = project.timeline.tracks.find(
          (t2) => t2.type === "text" && t2.name === "Captions"
        );
        if (!captionsTrack) {
          const result = await addTrack("text", 0);
          if (!result?.success) return;
          const updatedProject = get().project;
          const newTracks = updatedProject.timeline.tracks.filter(
            (t2) => t2.type === "text" && !project.timeline.tracks.some((old) => old.id === t2.id)
          );
          captionsTrack = newTracks[0];
          if (captionsTrack) {
            set((state) => ({
              project: {
                ...state.project,
                timeline: {
                  ...state.project.timeline,
                  tracks: state.project.timeline.tracks.map(
                    (t2) => t2.id === captionsTrack.id ? { ...t2, name: "Captions" } : t2
                  )
                }
              }
            }));
            captionsTrack = { ...captionsTrack, name: "Captions" };
          }
        }
        if (!captionsTrack) return;
        const duration = subtitle.endTime - subtitle.startTime;
        const style = subtitle.style;
        createTextClip(
          captionsTrack.id,
          subtitle.startTime,
          subtitle.text,
          duration,
          style ? {
            fontFamily: style.fontFamily,
            fontSize: style.fontSize,
            color: style.color,
            backgroundColor: style.backgroundColor || void 0
          } : void 0
        );
      },
